'use strict';

// Greasy Fork caps each script record at 2 MiB, and the core library spent this
// release sitting against that cap: relighting one theme lane consumed the last
// 3.2 KB, and the only lever left was deleting the comments that explained why
// each surface needed relighting. The generator strips whole-line comments from
// bundled module bodies now, which reclaimed about 193 KB.
//
// This pins a floor so the next feature that fills the bundle fails loudly here
// rather than by making someone shave prose off a code comment.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const sync = require('../sync-userscript.js');

const repoRoot = path.join(__dirname, '..');
const MAX_CODE_BYTES = 2 * 1024 * 1024;
const MIN_CORE_HEADROOM = 50 * 1024;

test('the core library keeps real headroom under the host cap', () => {
    const bytes = fs.statSync(path.join(repoRoot, 'YTKit-core.user.js')).size;
    const headroom = MAX_CODE_BYTES - bytes;
    assert.ok(headroom > 0,
        `YTKit-core.user.js is ${bytes} B, over the ${MAX_CODE_BYTES} B host cap`);
    assert.ok(headroom >= MIN_CORE_HEADROOM,
        `only ${headroom} B of core headroom left, below the ${MIN_CORE_HEADROOM} B floor. `
        + 'Reclaim space in sync-userscript.js rather than trimming source comments.');
});

test('bundled module bodies carry no whole-line comments', () => {
    const core = fs.readFileSync(path.join(repoRoot, 'YTKit-core.user.js'), 'utf8');
    // The generator's own module markers are the one exception: they are added
    // after stripping and the drift checker slices the library by them.
    const commentLines = core.split('\n')
        .map((line) => line.trim())
        .filter((line) => line.startsWith('//'))
        .filter((line) => !/^\/\/m:[0-9a-z]+$/.test(line))
        .filter((line) => !line.startsWith('// =='))
        .filter((line) => !line.startsWith('// @'))
        .filter((line) => !line.includes('bundled core modules'));
    // Every survivor has to be one the stripper is ENTITLED to keep.
    //
    // This used to be a bare count under 40, which is a proxy for size that the
    // headroom floor above already measures directly. The stripper now refuses
    // to drop any line carrying a quote, a backtick or an interpolation, so
    // that a scanner mistake costs a few bytes of surviving comment rather than
    // silently deleting a line of data out of a shipped string. Counting alone
    // could not tell the two apart.
    const CARRIES_DATA = /['"`]|${/;
    const unexplained = commentLines
        .filter((line) => !CARRIES_DATA.test(line))
        .filter((line) => !line.startsWith('// Generated by sync-userscript.js'));
    assert.deepEqual(unexplained, [],
        'a comment with no quote, backtick or interpolation in it should have been stripped');
    // A loose ceiling so an unbounded regression is still noisy.
    assert.ok(commentLines.length < 1200,
        `${commentLines.length} whole-line comments survived into the bundle; `
        + `first: ${JSON.stringify(commentLines.slice(0, 3))}`);
});

test('stripping never touches a line inside a template literal', () => {
    const backtick = String.fromCharCode(96);
    const sample = [
        'const a = 1;',
        '// removed',
        'const t = ' + backtick + 'first line',
        '// kept: this is template DATA',
        'last line' + backtick + ';',
        '// removed too'
    ].join('\n');
    const stripped = sync.stripSafeLineComments(sample);
    assert.ok(!stripped.includes('// removed'), 'a top-level comment must go');
    assert.ok(!stripped.includes('// removed too'),
        'and so must one after the template closes');
    assert.ok(stripped.includes('// kept: this is template DATA'),
        'a comment-looking line inside a template is data and must stay');
});

test('stripping leaves quoted and block-commented regions alone', () => {
    const sample = [
        "const s = 'a string with // inside it';",
        '/* a block comment',
        '// that contains a line comment',
        '*/',
        '// a real one',
        'const b = 2;'
    ].join('\n');
    const stripped = sync.stripSafeLineComments(sample);
    assert.ok(stripped.includes("'a string with // inside it'"),
        'a // inside a string is not a comment');
    assert.ok(stripped.includes('// that contains a line comment'),
        'a // inside a block comment belongs to that block');
    assert.ok(!stripped.includes('// a real one'), 'a genuine top-level comment goes');
});

// The re-parse guard was never the protection it was described as.
//
// shrinkModuleBody re-parsed each stripped body with new Function and reverted
// on failure, and the claim was that a mangled module "can only fail to shrink,
// never reach the bundle". Stripping removes WHOLE LINES, so the newlines
// survive and a strip essentially cannot produce a syntax error — the guard has
// nothing to catch. The test that covered it was vacuous too: its fixture had
// no comment in it, so stripSafeLineComments returned it byte-identical and
// shrinkModuleBody took the early return before new Function was ever called.
//
// What actually protects the bundle is the scanner being right about which
// lines are code, plus a refusal to drop any line carrying data characters.
// These test that, with the two constructs that measurably corrupted the
// shipped output before.

function evaluateModule(source) {
    const shim = { exports: {} };
    // eslint-disable-next-line no-new-func
    new Function('module', 'exports', source)(shim, shim.exports);
    return JSON.stringify(shim.exports, (key, value) =>
        (value instanceof RegExp ? value.source : value));
}

test('a comment-looking line inside a nested template survives stripping', () => {
    const backtick = String.fromCharCode(96);
    const dollar = String.fromCharCode(36);
    // The old scanner counted backtick DEPTH, so the backtick opening a
    // template nested inside a ${ } expression was read as the one closing the
    // outer template. Everything after it scanned as code.
    const source = [
        'const inner = (v) => v;',
        'const out = ' + backtick + 'outer',
        'A',
        dollar + '{inner(' + backtick + 'x',
        '// this line is DATA inside the nested template',
        'y' + backtick + ')}',
        'B' + backtick + ';',
        'module.exports = out;'
    ].join('\n');
    assert.doesNotThrow(() => evaluateModule(source), 'the fixture itself must be valid');

    const stripped = sync.stripSafeLineComments(source);
    assert.equal(evaluateModule(stripped), evaluateModule(source),
        'stripping must not change what the module produces');
});

test('a regex literal containing a backtick does not desync the scan', () => {
    const backtick = String.fromCharCode(96);
    // No regex handling at all before this: the backtick inside the character
    // class flipped the scanner into "inside a template" for the rest of the
    // file, and the real template's data line was deleted.
    const source = [
        'const re = /[' + backtick + ']/;',
        'const s = ' + backtick + 'head',
        '// data line inside a real template literal',
        'tail' + backtick + ';',
        'module.exports = { re, s };'
    ].join('\n');
    assert.doesNotThrow(() => evaluateModule(source), 'the fixture itself must be valid');

    const stripped = sync.stripSafeLineComments(source);
    assert.equal(evaluateModule(stripped), evaluateModule(source),
        'stripping must not change what the module produces');
});

test('a line carrying data characters is never dropped, comment or not', () => {
    const backtick = String.fromCharCode(96);
    const dollar = String.fromCharCode(36);
    const kept = [
        "// mentions 'a quote'",
        '// mentions a ' + backtick + 'backtick' + backtick,
        '// mentions ' + dollar + '{an interpolation}'
    ];
    const source = ['const a = 1;', ...kept, '// plain and strippable', 'module.exports = a;'].join('\n');
    const stripped = sync.stripSafeLineComments(source);
    for (const line of kept) {
        assert.ok(stripped.includes(line),
            'a comment carrying data characters is kept, so a scanner mistake costs bytes rather than data');
    }
    assert.ok(!stripped.includes('// plain and strippable'),
        'a comment with nothing data-like in it is still removed');
});

test('the stripper is applied through a guard that can hand back the original', () => {
    const source = fs.readFileSync(path.join(repoRoot, 'sync-userscript.js'), 'utf8');
    assert.match(source, /function shrinkModuleBody\(body, relativePath\)/,
        'the guard must still wrap the stripper');
    assert.match(source, /return body;/,
        'and hand back the original when the stripped body is not usable');
    // A body with nothing to strip comes back identical, byte for byte.
    const inert = 'const x = 1;\nmodule.exports = x;';
    assert.equal(sync.shrinkModuleBody(inert, 'test/fixture.js'), inert);
});

// WHEN a division follows a word that is only a keyword in some positions, the
// scanner SHALL read it as a division. `of`, `in` and `new` are all ordinary
// property names and `of` is an ordinary variable name; reading the `/` after
// one as a regex walked the scan into the rest of the line and swallowed the
// backtick that opened the next template, deleting a comment-shaped line out of
// template DATA. All four of these changed meaning before this.
test('a division after a contextual keyword is not read as a regex', () => {
    const backtick = String.fromCharCode(96);
    const HEADS = [
        ['a variable named of', 'const g = 2, of = 4; const q = of / g, t = ' + backtick + 'a/b'],
        ['a property named of', 'const g = 2, box = { of: 4 }; const q = box.of / g, t = ' + backtick + 'a/b'],
        ['a property named new', 'const g = 2, q = { new: 4 }; const z = q.new / g, t = ' + backtick + 'a/b'],
        ['a property named in', 'const g = 2, o = { in: 4 }; const z = o.in / g, t = ' + backtick + 'a/b']
    ];

    for (const [label, head] of HEADS) {
        const source = [
            head,
            '// THIS LINE IS TEMPLATE DATA',
            'tail' + backtick + ';',
            'module.exports = t;'
        ].join('\n');
        assert.doesNotThrow(() => evaluateModule(source), `${label}: the fixture itself must be valid`);
        const stripped = sync.stripSafeLineComments(source);
        assert.equal(evaluateModule(stripped), evaluateModule(source),
            `${label}: stripping must not change what the module produces`);
    }
});

// WHEN a `/` is in a genuine keyword position, it SHALL still be read as a
// regex — the fix must not buy safety by giving up on regexes.
test('a regex after a real keyword is still a regex', () => {
    const backtick = String.fromCharCode(96);
    const source = [
        'function f() { return /a\\/b/.source; }',
        'const t = ' + backtick + 'a/b',
        '// THIS LINE IS TEMPLATE DATA',
        'tail' + backtick + ';',
        'module.exports = { f: f(), t };'
    ].join('\n');
    assert.doesNotThrow(() => evaluateModule(source));
    assert.equal(evaluateModule(sync.stripSafeLineComments(source)), evaluateModule(source));
});

// WHEN a candidate regex would swallow a backtick or quote that is NOT inside a
// character class, the scanner SHALL prefer the division reading. That is the
// signature of a misread division, and preferring division costs at most a
// surviving comment where the other way costs a line of shipped data.
test('a character class may contain a backtick without tripping the guard', () => {
    const backtick = String.fromCharCode(96);
    const source = [
        'const re = /[' + backtick + ']/;',
        'const s = ' + backtick + 'head',
        '// data line inside a real template literal',
        'tail' + backtick + ';',
        'module.exports = { re: re.source, s };'
    ].join('\n');
    assert.doesNotThrow(() => evaluateModule(source));
    const stripped = sync.stripSafeLineComments(source);
    assert.equal(evaluateModule(stripped), evaluateModule(source),
        'a backtick inside [] is an ordinary pattern, not a misread division');
});

// CSS compaction used to find stylesheets three ways: a named const, a named
// `return`, and a backtick scan over an allowlist of eleven modules. A module
// that grew a new stylesheet was compacted only if someone remembered to list
// it. It is one parser-driven pass over every module now, and these pin what
// that pass may and may not touch.
const tick = String.fromCharCode(96);
const dollar = String.fromCharCode(36);

test('every bundled module compacts with its CSS intact and still parses', () => {
    let saved = 0;
    for (const rel of sync.V5_BUNDLE_MODULES) {
        const source = fs.readFileSync(path.join(repoRoot, rel), 'utf8');
        // compactBundledCssTemplates runs the rule-fragment round trip on every
        // template it rewrites and throws on a loss, so not throwing is the check.
        const compacted = sync.compactBundledCssTemplates(source, rel);
        // eslint-disable-next-line no-new-func
        assert.doesNotThrow(() => new Function(compacted), `${rel} must still parse after compaction`);
        saved += source.length - compacted.length;
    }
    assert.ok(saved > 200_000, `compaction reclaimed only ${saved} B across the bundle`);
});

test('a stylesheet in a module nothing ever listed is compacted anyway', () => {
    const source = [
        'injectStyle(' + tick,
        '    .brand-new-surface {',
        '        color: red;',
        '        margin: 0 auto;',
        '    }',
        tick + ');'
    ].join('\n');
    assert.equal(
        sync.compactBundledCssTemplates(source, 'extension/features/not-yet-written/index.js'),
        'injectStyle(' + tick + '.brand-new-surface{color:red;margin:0 auto}' + tick + ');'
    );
});

test('code between two backticks in regex literals is never read as a stylesheet', () => {
    // A character scan pairs these two backticks and hands the function between
    // them to the compactor: it has a brace and an `a : b;`, which is all the CSS
    // shape test asks for. Joining its lines would glue the comment onto the code.
    const source = [
        'const open = /' + tick + '/;',
        'function pick(x, a, b) {',
        '    // keep: this comment ends here',
        '    return x ? a : b;',
        '}',
        'const close = /' + tick + '/;'
    ].join('\n');
    assert.equal(sync.compactBundledCssTemplates(source, 'fixture.js'), source);
});

test('tagged templates, escapes and JavaScript-looking templates are left alone', () => {
    const untouched = [
        // String.raw hands its raw text to a function, so whitespace is data.
        'const re = String.raw' + tick + '.a {\n    color: red;\n}' + tick + ';',
        // A backslash in the static text keeps the whole template out of reach.
        'const glyph = ' + tick + '.a::before {\n    content: "\\\\2014";\n}' + tick + ';',
        // Braces and `a : b;` again, but this is a script someone ships as text.
        'const script = ' + tick + '(() => {\n    const v = a ? b : c;\n})();' + tick + ';',
        'const html = ' + tick + '<style>\n.a { color: red; }\n</style>' + tick + ';',
        // Interpolations no longer keep a template out of reach, so a script
        // with one has to be recognised as a script. Joined into one line, the
        // comment here would swallow the assignment after it.
        'const boot = ' + tick + '\nif (window.ytcfg) {\n    // pick the playback mode\n    window.ytcfg.mode = '
            + dollar + '{cfg} ? on : off;\n}\n' + tick + ';',
        // A `//` line is the one script signal here. CSS has no line comments,
        // and joining lines would glue this one onto the rule after it.
        'const sheet = ' + tick + '\n.a {\n    color: red;\n}\n// generated below\n.b {\n    top: 0;\n}\n' + tick + ';'
    ];
    for (const source of untouched) {
        assert.equal(sync.compactBundledCssTemplates(source, 'fixture.js'), source, source);
    }
});

test('interpolations come through compaction byte for byte', () => {
    const source = 'const css = ' + tick + '\n'
        + '    .a ' + dollar + '{sel} .b {\n'
        + '        color: ' + dollar + '{ok ? \'x : y\' : \'z\'};\n'
        + '    }\n' + tick + ';';
    assert.equal(
        sync.compactBundledCssTemplates(source, 'fixture.js'),
        'const css = ' + tick + '.a ' + dollar + '{sel} .b{color:' + dollar + '{ok ? \'x : y\' : \'z\'}}' + tick + ';',
        'the descendant spaces around an interpolation stay, and the expression is not rewritten'
    );

    // One inside a CSS comment would be dropped with the comment, which changes
    // what the code evaluates. The template is skipped instead.
    const commented = 'const css = ' + tick + '\n/* ' + dollar + '{note} */\n.a {\n    color: red;\n}' + tick + ';';
    assert.equal(sync.compactBundledCssTemplates(commented, 'fixture.js'), commented);
});

test('the rule-fragment round trip catches a compactor that loses CSS', () => {
    const before = '.a {\n    color: red;\n    margin: 0 auto;\n}\n.b .c { top: 0; }';
    assert.doesNotThrow(() => sync.assertCssSurvives(before, '.a{color:red;margin:0 auto}.b .c{top:0}', 'fixture'));
    assert.throws(() => sync.assertCssSurvives(before, '.a{color:red}.b .c{top:0}', 'fixture'),
        /changed the stylesheet in fixture at token 3: expected ";", got "\}"/);
    // Whitespace that means something is not normalised away.
    assert.throws(() => sync.assertCssSurvives(before, '.a{color:red;margin:0auto}.b .c{top:0}', 'fixture'),
        /margin:0 auto/);
    assert.throws(() => sync.assertCssSurvives(before, '.a{color:red;margin:0 auto}.b.c{top:0}', 'fixture'),
        /\.b \.c/);

    // Order and count decide which declaration wins, so they are part of the
    // check. A set of fragments passed all three of these.
    const twoRules = '.a { color: red; }\n.b { color: blue; }';
    assert.throws(() => sync.assertCssSurvives('.a { color: red; }\n.b { color: red; }', '.a{color:red}.b{}', 'fixture'),
        /expected "color:red", got "\}"/, 'a dropped duplicate');
    assert.throws(() => sync.assertCssSurvives('.a { color: red; }\n.b { top: 0; }', '.a{}.b{top:0;color:red}', 'fixture'),
        /expected "color:red", got "\}"/, 'a declaration moved into another rule');
    assert.throws(() => sync.assertCssSurvives(twoRules, '.b{color:blue}.a{color:red}', 'fixture'),
        /at token 0: expected "\.a", got "\.b"/, 'two rules swapped');
});
